public void init()
{
    next init();

    FormRun formRun = this as FormRun;

    // Build a map of Vendor InvoiceId -> VendNettingTransView
    Map                     vendInvoiceMap          = new Map(Types::String, Types::Class);
    VendNettingTransView    vendNettingTrans        = VendNettingTransView_ds.cursor();

    while (vendNettingTrans)
    {
        if (vendNettingTrans.Invoice)
        {
            vendInvoiceMap.insert(vendNettingTrans.Invoice, vendNettingTrans);
        }
        vendNettingTrans = vendNettingTransView_ds.getNext();
    }

    // Loop through Customer transactions and mark if InvoiceId matches a Vendor transaction
    CustNettingTransTotalView custNettingTrans = CustNettingTransTotalView_ds.cursor();

    while (custNettingTrans)
    {
        if (custNettingTrans.Invoice && vendInvoiceMap.exists(custNettingTrans.invoice))
        {
            // Mark both customer and vendor transactions
            formRun.markCustTrans(custNettingTrans);
            formRun.markVendTrans(vendInvoiceMap.lookup(custNettingTrans.Invoice));
        }
        custNettingTrans = custNettingTransTotalView_ds.getNext();
    }

    // Recalculate totals and update UI
    formRun.calculateNettingTotal();
    formRun.setUpNettingAmountControl();
    formRun.refreshDataSource();
    formRun.managePostButton();
}
